        const llm_grid_h = Math.floor(grid_thw[1] / spatial_merge_size);
        const llm_grid_w = Math.floor(grid_thw[2] / spatial_merge_size);
        const seq_len = llm_grid_h * llm_grid_w * llm_grid_t;
