        const h_pos = Array.from(
          { length: seq_len },
          (_8, i) => start_position + Math.floor(i / (llm_grid_w * llm_grid_t))
        );
        const w_pos = Array.from({ length: seq_len }, (_8, i) => start_position + i % llm_grid_w);
